'use strict';

import { Util } from 'calendar.util';
import { Type, Event, Loc, Dom, Runtime, Text, Tag } from 'main.core';
import { Entry, EntryManager } from 'calendar.entry';
import { MeetingStatusControl, IntranetButton, PlannerLimitHint } from 'calendar.controls';
import { BaseEvent, EventEmitter } from 'main.core.events';
import { Planner } from 'calendar.planner';
import { BitrixVue } from 'ui.vue3';
import { ViewEventSlider } from './view-event-slider';
import { CalendarSection } from 'calendar.sectionmanager';
import 'viewer';
import { DateTimeFormat } from 'main.date'; // need for planner.js
import { RelationInterface } from 'calendar.entityrelation';
import { AvatarRoundGuest } from 'ui.avatar';

export class EventViewForm
{
	permissions = {};
	name = 'eventviewform';
	uid = null;
	DOM = {};
	RELOAD_REQUESTED = 'RELOAD_REQUESTED';
	RELOAD_FINISHED = 'RELOAD_FINISHED';
	reloadStatus = null;
	entityChanged = false;
	LOAD_DELAY = 500;
	app = null;
	// Planner.update replaces accessibility, so partial responses are accumulated within a snapshot.
	prevUserList = [];
	loadedAccessibilityData = {};
	allUsersAccessibilityLoaded = false;
	currentPlannerData = null;
	plannerRequestId = 0;
	plannerLimitState = null;
	plannerLimitHint = null;
	plannerRevealTimeout = null;
	destroyed = false;

	constructor(options = {})
	{
		this.type = options.type || 'user';
		this.attendees = [];
		this.ownerId = options.ownerId || 0;
		this.userId = options.userId || 0;
		this.zIndex = 3100;
		this.entryId = options.entryId || null;
		this.calendarContext = options.calendarContext || null;
		this.entryDateFrom = options.entryDateFrom || null;
		this.timezoneOffset = options.timezoneOffset ?? null;
		this.BX = Util.getBX();

		this.sliderOnLoad = this.onLoadSlider.bind(this);
		this.showUserListPopupBind = this.showUserListPopup.bind(this);
		this.keyHandlerBind = this.keyHandler.bind(this);
		this.destroyBind = this.destroy.bind(this);
		this.reloadPlannerFromPullBind = this.reloadPlannerFromPull.bind(this);
		this.handleToggleAttendeesListBind = this.handleToggleAttendeesList.bind(this);

		this.loadPlannerDataDebounce = Runtime.debounce(this.loadPlannerData, this.LOAD_DELAY, this);

		this.pullEventList = new Set();
	}

	initInSlider(slider, promiseResolve)
	{
		this.slider = slider;
		EventEmitter.subscribe(slider, 'SidePanel.Slider:onLoad', this.sliderOnLoad);
		EventEmitter.subscribe(slider, 'SidePanel.Slider:onCloseComplete', this.destroyBind);
		Event.bind(document, 'keydown', this.keyHandlerBind);

		this
			.createContent(slider)
			.then((html) => {
				if (Type.isFunction(promiseResolve))
				{
					promiseResolve(html);
				}
			});

		this.opened = true;
	}

	isOpened()
	{
		return this.opened;
	}

	destroy()
	{
		this.destroyed = true;
		this.plannerRequestId += 1;

		EventEmitter.unsubscribe(this.slider, 'SidePanel.Slider:onLoad', this.sliderOnLoad);
		EventEmitter.unsubscribe(this.slider, 'SidePanel.Slider:onCloseComplete', this.destroyBind);
		Event.unbind(document, 'keydown', this.keyHandlerBind);

		if (this.planner)
		{
			this.planner.unsubscribe('onToggleAttendeesList', this.handleToggleAttendeesListBind);
			this.planner.destroy();
			this.planner = null;
		}
		clearTimeout(this.plannerRevealTimeout);
		this.plannerRevealTimeout = null;
		this.plannerLimitHint?.destroy();
		this.plannerLimitHint = null;

		if (this.app)
		{
			this.app.unmount();
		}

		if (this.intranetControllButton && this.intranetControllButton.destroy)
		{
			this.intranetControllButton.destroy();
		}

		Util.closeAllPopups();
		this.opened = false;
	}

	onLoadSlider(event)
	{
		if (!event instanceof BaseEvent)
		{
			return;
		}
		const data = event.getData();
		const slider = data[0]?.slider;

		this.DOM.content = slider.layout.content;

		// Used to execute javasctipt and attach CSS from ajax responce
		this.BX.html(slider.layout.content, slider.getData().get('sliderContent'));
		if (!Type.isNull(this.uid))
		{
			this.initControls(this.uid);
		}

		this.reloadStatus = this.RELOAD_FINISHED;
	}

	loadComponentAssets(json)
	{
		if (!json)
		{
			return;
		}
		const assets = JSON.parse(json).data.assets;
		const promise = new Promise((resolve, reject) => {
			const css = assets.css;
			BX.load(css, () => {
				BX.loadScript(assets.js, resolve);
			});
		});
		promise.then(() => {
			const strings = assets.string;
			const stringAsset = strings.join('\n');
			BX.html(document.head, stringAsset, { useAdjacentHTML: true });
		});
	}

	createContent(slider)
	{
		return new Promise((resolve) => {
			this.BX.ajax.runAction('calendar.api.calendareventviewform.getCalendarViewSliderParams', {
				data: {
					entryId: this.entryId,
					dateFrom: Util.formatDate(this.entryDateFrom),
					timezoneOffset: this.timezoneOffset,
				},
				analytics: {
					tool: 'im',
					category: 'events',
					event: 'view_card',
					c_section: 'card_full',
					p5: `eventId_${this.entryId}`,
				},
			}).then(
				(response) => {
					const viewEventSliderRoot = document.createElement('div');

					if ((Type.isFunction(slider.isOpen) && slider.isOpen()) || slider.isOpen === true)
					{
						const params = response.data;
						params.eventExists = Boolean(params.entry.ID);
						this.attendees = [];

						for (const status in params.attendees)
						{
							this.attendees.push(...params.attendees[status]);
						}

						// load components' css and js
						if (params.filesView)
						{
							this.loadComponentAssets(params.filesView);
						}

						if (params.crmView)
						{
							this.loadComponentAssets(params.crmView);
							this.BX.ajax.runAction('calendar.api.calendareventviewform.getCrmView', {
								data: { signedEvent: params.signedEvent },
							});
						}

						// set vue component to slider
						this.app = BitrixVue.createApp(ViewEventSlider, {
							params,
							// Pull-driven planner reload goes through the inactive-tab guard.
							reloadPlannerCallback: this.reloadPlannerFromPullBind,
							showUserListPopupCallback: this.showUserListPopupBind,
						});
						this.app.mount(viewEventSliderRoot);

						slider.sliderContent = viewEventSliderRoot;

						// set local params
						this.userId = params.userId;
						this.uid = params.id;
						this.entryUrl = params.entryUrl;
						this.userTimezone = params.userTimezone;
						this.plannerFeatureEnabled = Boolean(params.plannerFeatureEnabled);
						if (this.planner && !this.plannerFeatureEnabled)
						{
							this.planner.lock();
						}
						this.handleEntryData(params.entry, params.userIndex, params.section);

						this.isCollabUser = params.isCollabUser;
						this.downloadIcsEnabled = params.downloadIcsEnabled;
					}

					resolve(viewEventSliderRoot);
				},
				(response) => {
					if (response.errors && response.errors.length > 0)
					{
						slider.getData().set(
							'sliderContent',
							'<div class="calendar-slider-alert">'
						+ '<div class="calendar-slider-alert-inner">'
						+ '<div class="calendar-slider-alert-img"></div>'
						+ `<h1 class="calendar-slider-alert-text">${Text.encode(response.errors[0].message)}</h1>`
						+ '</div>'
						+ '</div>',
						);
					}

					if (response.data && !Type.isNil(response.data.isAvailable) && !response.data.isAvailable)
					{
						const showHelperCallback = () => {
							top.BX.UI.InfoHelper.show('limit_office_calendar_off', {
								isLimit: true,
								limitAnalyticsLabels: {
									module: 'calendar',
									source: 'eventViewForm',
								},
							});
						};

						if (this.slider)
						{
							this.slider.close(true, showHelperCallback);
						}
						else
						{
							showHelperCallback();
						}
					}

					console.error(response.errors);
					resolve(response);
				},
			);
		});
	}

	initControls(uid)
	{
		this.DOM.title = this.DOM.content.querySelector(`#${uid}_title`);
		this.DOM.buttonSet = this.DOM.content.querySelector(`#${uid}_buttonset`);
		this.DOM.editButton = this.DOM.content.querySelector(`#${uid}_but_edit`);
		if (this.downloadIcsEnabled)
		{
			this.DOM.downloadButton = this.DOM.content.querySelector(`#${uid}_but_download`);
		}
		this.DOM.delButton = this.DOM.content.querySelector(`#${uid}_but_del`);
		this.DOM.sidebarInner = this.DOM.content.querySelector(`#${uid}_sidebar_inner`);

		if (this.DOM.buttonSet)
		{
			this.initPlannerControl(uid);
		}

		const innerTimeWrap = this.DOM.content.querySelector(`#${uid}_time_inner_wrap`);
		if (Type.isElementNode(innerTimeWrap) && innerTimeWrap.offsetHeight > 50)
		{
			Dom.addClass(this.DOM.content.querySelector(`#${uid}_time_wrap`), 'calendar-slider-sidebar-head-long-time');
		}

		if ((this.canDo('edit') || this.canDo('editLocation') || this.canDo('editAttendees')) && this.DOM.editButton)
		{
			Event.bind(this.DOM.editButton, 'click', this.handleEditButtonClick.bind(this));
		}

		if (this.DOM.sidebarInner)
		{
			// Reminder
			this.DOM.reminderWrap = this.DOM.sidebarInner.querySelector('.calendar-slider-sidebar-remind-wrap');
			if (Type.isDomNode(this.DOM.reminderWrap))
			{
				Dom.clean(this.DOM.reminderWrap);
				const viewMode = !this.canDo('edit')
					&& this.entry.getCurrentStatus() === false;

				this.reminderControl = new this.BX.Calendar.Controls.Reminder({
					wrap: this.DOM.reminderWrap,
					zIndex: this.zIndex,
					viewMode,
				});
				this.reminderControl.setValue(this.entry.getReminders());

				if (!viewMode)
				{
					this.reminderControl.subscribe('onChange', (event) => {
						if (event instanceof BaseEvent)
						{
							this.handleEntityChanges();
							this.reminderValues = event.getData().values;
							this.BX.ajax.runAction('calendar.api.calendarajax.updateReminders', {
								data: {
									entryId: this.entry.id,
									userId: this.userId,
									reminders: this.reminderValues,
								},
							});
						}
					});
				}
			}

			const items = this.DOM.sidebarInner.querySelectorAll('.calendar-slider-sidebar-border-bottom');
			if (items.length >= 2)
			{
				this.BX.removeClass(items[items.length - 1], 'calendar-slider-sidebar-border-bottom');
			}
		}

		if (this.downloadIcsEnabled)
		{
			Event.bind(this.DOM.downloadButton, 'click', () => EntryManager.downloadIcs(this.entryId));
		}

		if (this.canDo('delete'))
		{
			Event.bind(this.DOM.delButton, 'click', () => {
				EventEmitter.subscribeOnce('BX.Calendar.Entry:beforeDelete', () => {
					this.BX.SidePanel.Instance.close();
				});
				EntryManager.deleteEntry(this.entry, this.calendarContext);
			});
		}
		else
		{
			this.BX.remove(this.DOM.delButton);
		}

		const filesWrap = `${uid}_${this.entry.id}_files_wrap`;
		if (filesWrap)
		{
			const currentTop = (typeof window.top.BX.viewElementBind === 'function' ? window.top.BX : window.BX);
			currentTop.viewElementBind(
				filesWrap,
				{
					showTitle: true,
				},
				(node) => {
					return Type.isElementNode(node) && (node.getAttribute('data-bx-viewer') || node.getAttribute('data-bx-image'));
				},
			);
		}

		this.DOM.relationWrap = this.DOM.content.querySelector(`#${uid}_view_relation_wrap`);

		if (
			this.DOM.relationWrap
			&& this.canDo('view')
			&& ['#shared_crm#', '#booking#'].includes(this.entry?.data?.EVENT_TYPE)
		)
		{
			this.relationControl = new RelationInterface({
				parentNode: this.DOM.relationWrap,
				eventId: this.entry.parentId,
			});
			Dom.append(this.relationControl.render(), this.DOM.relationWrap);
		}

		if (this.entry && this.entry.isMeeting())
		{
			this.initAcceptMeetingControl(uid);
		}

		if (this.DOM.sidebarInner)
		{
			const items = this.DOM.sidebarInner.querySelectorAll('.calendar-slider-sidebar-border-bottom');
			if (items.length >= 2)
			{
				this.BX.removeClass(items[items.length - 1], 'calendar-slider-sidebar-border-bottom');
			}
		}

		this.DOM.copyButton = this.DOM.content.querySelector(`#${uid}_copy_url_btn`);
		if (this.DOM.copyButton)
		{
			Event.bind(this.DOM.copyButton, 'click', this.copyEventUrl.bind(this));
		}

		// Init "Videocall" control
		this.DOM.videoCall = this.DOM.sidebarInner.querySelector('.calendar-slider-sidebar-videocall');
		Dom.clean(this.DOM.videoCall);
		if (
			Type.isElementNode(this.DOM.videoCall)
			&& this.entry
			&& this.entry.data.PARENT_ID
			&& (
				this.entry.data.EVENT_TYPE === '#shared#'
				|| this.entry.data.EVENT_TYPE === '#shared_crm#'
			)
		)
		{
			this.DOM.videoCall.style.display = '';
			this.conferenceButton = Tag.render`
				<div class="ui-btn-split ui-btn-icon-camera-blue intranet-control-btn ui-btn-light-border ui-btn-icon-inline" style="width: 100%">
					<button class="ui-btn-main calendar-slider-conference-button">
						${Loc.getMessage('EC_CALENDAR_CONFERENCE')}
					</button>
				</div>
			`;
			Event.bind(this.conferenceButton, 'click', this.handleConferenceButtonClick.bind(this));

			Dom.append(this.conferenceButton, this.DOM.videoCall);
		}
		else if (
			BX?.Intranet?.ControlButton
			&& Type.isElementNode(this.DOM.videoCall)
			&& this.entry.getCurrentStatus() !== false
		)
		{
			this.DOM.videoCall.style.display = '';

			const items = this.isCollabUser
				? ['chat', 'videocall', 'task']
				: ['chat', 'videocall', 'blog_post', 'task']
			;

			this.intranetControllButton = new IntranetButton({
				intranetControlButtonParams: {
					items,
					container: this.DOM.videoCall,
					entityType: 'calendar_event',
					entityId: this.entry.parentId,
					entityData: {
						dateFrom: Util.formatDate(this.entry.from),
						parentId: this.entry.parentId,
					},
					analytics: {
						startVideoCall: {
							tool: 'im',
							category: 'events',
							event: 'click_call',
							type: 'group',
							c_section: 'card_full',
							c_sub_section: 'context_menu',
							p5: `eventId_${this.entry.parentId}`,
						},
					},
				},
				callbacks: {
					getUsersCount: () => this.attendees.length,
					hasChat: () => this.entry.data?.MEETING?.CHAT_ID > 0,
				},
			});
		}
		else
		{
			this.DOM.videoCall.style.display = 'none';
		}
	}

	handleEntryData(data, userIndex, sectionData)
	{
		this.entry = new Entry({ data, userIndex });
		this.section = new CalendarSection(sectionData);

		if (Type.isPlainObject(sectionData))
		{
			this.permissions = sectionData.PERM;
		}

		EntryManager.registerEntrySlider(this.entry, this);
	}

	initPlannerControl(uid)
	{
		this.plannerId = `${uid}_view_slider_planner`;
		this.DOM.plannerWrapOuter = this.DOM.content.querySelector('.calendar-slider-detail-timeline');
		this.DOM.plannerWrap = this.DOM.plannerWrapOuter.querySelector('.calendar-view-planner-wrap');
		Dom.clean(this.DOM.plannerWrap);
		this.planner = new Planner({
			wrap: this.DOM.plannerWrap,
			minWidth: parseInt(this.DOM.plannerWrap.offsetWidth),
			solidStatus: true,
			readonly: true,
			locked: !this.plannerFeatureEnabled,
			alwaysBlue: true,
		});

		if (Type.isDate(this.entry.from))
		{
			this.planner.currentFromDate = new Date(this.entry.from.getTime());
			this.planner.currentToDate = this.entry.isLongWithTime()
				? new Date(this.entry.from.getTime())
				: new Date(this.entry.to.getTime());
		}

		// Lazy accessibility load: when the user expands the attendees list, load the
		// accessibility of the deferred attendees that was skipped on open.
		this.planner.subscribe('onToggleAttendeesList', this.handleToggleAttendeesListBind);

		this.planner.show();
		this.planner.showLoader();

		this.plannerRevealTimeout = setTimeout(() => {
			if (this.DOM.plannerWrapOuter)
			{
				Dom.removeClass(this.DOM.plannerWrapOuter, 'hidden');
			}
		}, 500);

		this.currentPlannerData = null;
		const plannerData = this.getPlannerData();
		this.currentPlannerData = plannerData;
		this.plannerRequestId += 1;

		// Lazy accessibility load: on open compute only the priority portion
		// (the planner's initial visible rows), defer the rest.
		// prevUserList is used more broadly than its original meaning ("already loaded"):
		// here it also holds not-yet-loaded deferred users so the server skips them.
		this.loadedAccessibilityData = {};
		this.prevUserList = this.getDeferredUserIds(plannerData.entityList, plannerData.hostId);
		this.allUsersAccessibilityLoaded = false;

		this.loadPlannerDataDebounce(plannerData, this.plannerRequestId);
	}

	getPlannerData()
	{
		return this.currentPlannerData ?? {
			entryId: this.entry.id || 0,
			entryLocation: this.entry.data.LOCATION || '',
			ownerId: this.ownerId,
			hostId: this.entry.getMeetingHost(),
			type: this.type,
			entityList: this.entry.getAttendeesEntityList(),
			attendeesProvided: 'Y',
			dateFrom: Util.formatDate(this.entry.from.getTime() - Util.getDayLength() * 3),
			dateTo: Util.formatDate(this.entry.to.getTime() + Util.getDayLength() * 10),
			timezone: this.userTimezone,
			location: this.entry.getLocation(),
			entry: this.entry,
		};
	}

	handleToggleAttendeesList(event)
	{
		if (!(event instanceof BaseEvent))
		{
			return;
		}

		// Load the deferred accessibility only once, on the first expand.
		// Re-expanding/collapsing must not trigger new requests.
		if (event.getData().expanded !== true || this.allUsersAccessibilityLoaded)
		{
			return;
		}

		this.allUsersAccessibilityLoaded = true;
		if (!this.prevUserList.some((id) => Type.isUndefined(this.loadedAccessibilityData[id])))
		{
			return;
		}

		// prevUserList currently holds both the deferred users (added on open so the server
		// skips them) and the already-loaded priority users. Keep only the loaded ones, so
		// this request computes the deferred attendees while not re-requesting the loaded ones.
		this.prevUserList = this.prevUserList.filter((id) => !Type.isUndefined(this.loadedAccessibilityData[id]));

		// Not debounced: this is an explicit user action, not a pull-driven reload, so it must
		// not be delayed or coalesced with background reloads and is not subject to the tab guard.
		this.loadPlannerData(this.getPlannerData());
	}

	reloadPlannerFromPull(plannerData)
	{
		if (this.destroyed)
		{
			return;
		}

		this.plannerRequestId += 1;
		this.currentPlannerData = plannerData;
		this.loadedAccessibilityData = {};
		this.prevUserList = this.allUsersAccessibilityLoaded
			? []
			: this.getDeferredUserIds(plannerData.entityList, plannerData.hostId);

		this.loadPlannerDataDebounce(plannerData, this.plannerRequestId);
	}

	getDeferredUserIds(entityList, hostId)
	{
		if (!Type.isArray(entityList) || entityList.some((entity) => entity?.entityId !== 'user'))
		{
			return [];
		}

		const normalizedUserIds = entityList
			.filter((entity) => /^[0-9]+$/.test(entity.id))
			.map((entity) => Number(entity.id))
			.filter((id) => Number.isSafeInteger(id) && id > 0)
		;
		const userIds = [...new Set(normalizedUserIds)];
		const hostIndex = userIds.indexOf(Number(hostId));
		if (hostIndex > 0)
		{
			userIds.unshift(...userIds.splice(hostIndex, 1));
		}

		// Planner shows all rows at the +1 boundary without offering expansion.
		const initialLimit = this.planner.initialMinEntryRows;
		if (userIds.length <= initialLimit + 1)
		{
			return [];
		}

		return userIds.slice(initialLimit);
	}

	showUserListPopup(node, userList)
	{
		if (this.userListPopup)
		{
			this.userListPopup.close();
		}

		if (userList && userList.length > 0)
		{
			this.DOM.userListPopupWrap = this.BX.create('DIV', { props: { className: 'calendar-user-list-popup-block' } });
			userList.forEach(function(user)
			{
				let userAvatar = `
					<div class="ui-icon ui-icon-common-user" style="width: 34px; height: 34px;">
						<i></i>
					</div>
				`;
				if (user.AVATAR && user.AVATAR !== '/bitrix/images/1.gif')
				{
					userAvatar = `<img src="${encodeURI(user.AVATAR)}" width="34" height="34">`;
				}

				if (user.EMAIL_USER)
				{
					userAvatar = `
						<div class="ui-icon ui-icon ui-icon-common-user-mail" style="width: 34px; height: 34px;">
							<i></i>
						</div>
					`;
				}

				if (user.SHARING_USER)
				{
					userAvatar = `
						<div class="ui-icon ui-icon-common-user ui-icon-common-user-sharing" style="width: 34px; height: 34px;">
							<i></i>
						</div>
					`;
				}

				if (user.COLLAB_USER)
				{
					const userpicPath = user.AVATAR && user.AVATAR !== '/bitrix/images/1.gif'
						? user.AVATAR
						: null
					;
					userAvatar = new AvatarRoundGuest(
						{
							size: 34,
							userName: user.DISPLAY_NAME,
							userpicPath,
							baseColor: '#19cc45',
						},
					).getContainer();
				}

				const userWrap = Tag.render`
					<div class="calendar-slider-sidebar-user-container calendar-slider-sidebar-user-card">
						<div class="calendar-slider-sidebar-user-block-avatar">
							<div class="calendar-slider-sidebar-user-block-item">
								${userAvatar}
							</div>
						</div>
						<div class="calendar-slider-sidebar-user-info">
							<a href="${user.URL ? user.URL : '#'}" 
								class="calendar-slider-sidebar-user-info-name ${user.COLLAB_USER ? 'calendar-collab-user' : ''}"
							>
								${Text.encode(user.DISPLAY_NAME)}
							</a>
						</div>
					</div>
				`;
				this.DOM.userListPopupWrap.append(userWrap);
			}, this);

			this.userListPopup = this.BX.PopupWindowManager.create(`user-list-popup-${Math.random()}`, node, {
				autoHide: true,
				closeByEsc: true,
				offsetTop: 0,
				offsetLeft: node.offsetWidth / 2,
				resizable: false,
				lightShadow: true,
				content: this.DOM.userListPopupWrap,
				className: 'calendar-user-list-popup',
				maxWidth: 300,
				maxHeight: 500,
				zIndex: 4000,
				angle: {
					position: 'top',
				},
			});

			this.userListPopup.show();
			this.BX.addCustomEvent(this.userListPopup, 'onPopupClose', () => {
				this.userListPopup.destroy();
			});
		}
	}

	initAcceptMeetingControl(uid)
	{
		this.DOM.statusButtonset = this.DOM.content.querySelector(`#${uid}_status_buttonset`);
		this.DOM.statusButtonset.style.marginRight = '12px';

		if (this.entry.getCurrentStatus() === 'H' || this.entry.getCurrentStatus() === false)
		{
			Dom.remove(this.DOM.statusButtonset);
		}
		else
		{
			this.statusControl = new MeetingStatusControl(
				{
					wrap: this.DOM.statusButtonset,
					currentStatus: this.DOM.content.querySelector(`#${uid}_current_status`).value || this.entry.getCurrentStatus(),
				},
			);

			this.statusControl.subscribe('onSetStatus', (event) => {
				if (event instanceof BaseEvent)
				{
					this.handleEntityChanges();
					EntryManager.setMeetingStatus(this.entry, event.getData().status)
						.then(() => {
							this.statusControl.setStatus(this.entry.getCurrentStatus(), false);
							this.statusControl.updateStatus();

							if (this.entry.getCurrentStatus() === 'Y')
							{
								Event.bind(this.DOM.editButton, 'click', this.handleEditButtonClick.bind(this));
							}
							else
							{
								Event.unbind(this.DOM.editButton, 'click', this.handleEditButtonClick.bind(this));
							}

							EventEmitter.emit(`MeetingStatusControl_${uid}:onSetStatus`, event);
						})
						.catch(() => {});
				}
			});
		}
	}

	copyEventUrl()
	{
		if (!this.entryUrl || !this.BX.clipboard.copy(window.location.origin + this.entryUrl))
		{
			return;
		}

		this.timeoutIds = this.timeoutIds || [];
		const popup = new this.BX.PopupWindow(
			`calendar_clipboard_copy_${Text.getRandom().toLowerCase()}`,
			this.DOM.copyButton,
			{
				content: Loc.getMessage('CALENDAR_TIP_TEMPLATE_LINK_COPIED'),
				darkMode: true,
				autoHide: true,
				zIndex: 1000,
				angle: true,
				offsetLeft: 20,
				cachable: false,
			},
		);
		popup.show();

		let timeoutId;
		while (timeoutId = this.timeoutIds.pop())
		{
			clearTimeout(timeoutId);
		}
		this.timeoutIds.push(setTimeout(() => {
			popup.close();
		}, 1500));
	}

	canDo(action)
	{
		if ((action === 'edit' || action === 'delete'))
		{
			if (this.entry.isResourcebooking())
			{
				return false;
			}

			if (this.entry.permissions)
			{
				return this.entry.permissions?.edit;
			}

			return this.section.canDo('edit');
		}

		if ((action === 'view'))
		{
			if (this.entry.permissions)
			{
				return this.entry.permissions?.view_full;
			}

			return this.permissions.view_full;
		}

		const isInvitedOrRejected = ['Q', 'N'].includes(this.entry.getCurrentStatus());
		if (action === 'editLocation')
		{
			const canEdit = this.entry.permissions?.edit === true;
			const canEditLocation = this.entry.permissions?.editLocation === true;

			return !isInvitedOrRejected && (canEdit || canEditLocation);
		}

		if (action === 'editAttendees')
		{
			const canEdit = this.entry.permissions?.edit === true;
			const canEditAttendees = this.entry.permissions?.editAttendees === true;

			return !isInvitedOrRejected && (canEdit || canEditAttendees);
		}

		return false;
	}

	plannerIsShown()
	{
		return this.DOM.plannerWrap && Dom.hasClass(this.DOM.plannerWrap, 'calendar-edit-planner-wrap-shown');
	}

	loadPlannerData(plannerData, expectedRequestId = this.plannerRequestId)
	{
		if (this.destroyed || expectedRequestId !== this.plannerRequestId)
		{
			return Promise.resolve();
		}

		const requestPrevUserList = this.prevUserList;
		const requestId = (this.plannerRequestId += 1);

		// BX.ajax.runAction returns BX.Promise without finally().
		return Promise.resolve(this.BX.ajax.runAction('calendar.api.calendarajax.updatePlanner', {
			data: {
				...plannerData,
				attendeesProvided: 'Y',
				// prevUserList contains ids of users whose accessibility the server should skip.
				// The meeting room comes through a separate channel (location) and is not involved here.
				prevUserList: requestPrevUserList,
			},
		})).then(
			(response) => {
				// Ignore a response that is not from the latest dispatched request.
				if (requestId !== this.plannerRequestId)
				{
					return response;
				}

				const plannerLimitExceeded = this.applyPlannerLimitState(response.data);

				// Merge accessibility into the accumulator without overwriting the previously loaded data.
				for (const id in response.data.accessibility)
				{
					if (response.data.accessibility.hasOwnProperty(id))
					{
						this.loadedAccessibilityData[id] = response.data.accessibility[id];
					}
				}

				// Rebuild the accumulator from this request's skip list plus the users just loaded,
				// so it stays consistent regardless of concurrent paths.
				if (Type.isArray(response.data.entries))
				{
					const knownUserIds = new Set(plannerLimitExceeded ? [] : requestPrevUserList);
					response.data.entries.forEach((entry) => {
						const userId = parseInt(entry.id, 10);
						const hasAccessibility = this.loadedAccessibilityData[entry.id];
						if (entry.type === 'user' && !knownUserIds.has(userId) && hasAccessibility)
						{
							knownUserIds.add(userId);
						}
					});
					this.prevUserList = Array.from(knownUserIds);
				}

				this.planner.update(
					response.data.entries,
					this.loadedAccessibilityData,
				);

				this.planner.updateSelector(
					Util.adjustDateForTimezoneOffset(
						plannerData.entry.from,
						plannerData.entry.userTimezoneOffsetFrom,
						plannerData.entry.fullDay,
					),
					Util.adjustDateForTimezoneOffset(
						plannerData.entry.to,
						plannerData.entry.userTimezoneOffsetTo,
						plannerData.entry.fullDay,
					),
					plannerData.entry.fullDay,

				);

				return response;
			},
			(response) => response,
		).finally(() => {
			if (requestId === this.plannerRequestId)
			{
				this.planner?.hideLoader();
			}
		});
	}

	applyPlannerLimitState(data): boolean
	{
		const exceeded = data.plannerLimitExceeded === true;
		const wasExceeded = this.plannerLimitState?.exceeded ?? false;

		this.plannerLimitState = {
			exceeded,
			maxPlannerUsers: parseInt(data.maxPlannerUsers, 10) || 0,
			peopleCount: parseInt(data.plannerPeopleCount, 10) || 0,
		};

		if (exceeded)
		{
			this.loadedAccessibilityData = {};
			this.prevUserList = [];
		}

		if (exceeded !== wasExceeded)
		{
			this.handlePlannerLimitStateChange(new BaseEvent({
				data: { ...this.plannerLimitState },
			}));
		}

		return exceeded;
	}

	handlePlannerLimitStateChange(event: BaseEvent): void
	{
		if (!this.plannerFeatureEnabled)
		{
			return;
		}

		const { exceeded, maxPlannerUsers } = event.getData();
		if (exceeded)
		{
			this.getPlannerLimitHint(maxPlannerUsers)?.show();
		}
		else
		{
			this.plannerLimitHint?.close();
		}
	}

	getPlannerLimitHint(maxPlannerUsers: number): PlannerLimitHint | null
	{
		if (!this.plannerLimitHint && this.DOM.plannerWrapOuter)
		{
			this.plannerLimitHint = new PlannerLimitHint({
				bindElement: this.DOM.plannerWrapOuter,
				targetContainer: this.DOM.content,
				zIndex: this.zIndex,
				maxPlannerUsers,
			});
		}
		this.plannerLimitHint?.setMaxPlannerUsers(maxPlannerUsers);

		return this.plannerLimitHint;
	}

	keyHandler(e)
	{
		if (
			(
				e.keyCode === Util.getKeyCode('delete')
				// || e.keyCode === Util.getKeyCode('backspace')
			)
			&& this.canDo('delete'))
		{
			const target = event.target || event.srcElement;
			const tagName = Type.isElementNode(target) ? target.tagName.toLowerCase() : null;
			if (tagName && !['input', 'textarea'].includes(tagName))
			{
				EventEmitter.subscribeOnce('BX.Calendar.Entry:beforeDelete', () => {
					this.BX.SidePanel.Instance.close();
				});
				EntryManager.deleteEntry(this.entry, this.calendarContext);
			}
		}
	}

	handleEntityChanges()
	{
		this.entityChanged = true;
	}

	handleConferenceButtonClick()
	{
		if (this.conferenceButton)
		{
			Dom.addClass(this.conferenceButton, 'ui-btn-wait');
		}

		this.getConferenceChatId();

		if (this.conferenceButton)
		{
			Dom.removeClass(this.conferenceButton, 'ui-btn-wait');
		}
	}

	getConferenceChatId()
	{
		return this.BX.ajax.runAction('calendar.api.calendarajax.getConferenceChatId', {
			data: {
				eventId: this.entry.data.PARENT_ID,
			},
			analytics: {
				tool: 'im',
				category: 'events',
				event: 'click_call',
				type: 'videoconf',
				c_section: 'card_full',
				c_sub_section: 'card',
				p5: `eventId_${this.entry.parentId}`,
			},
		}).then(
			(response) => {
				if (top.window.BXIM && response.data && response.data.chatId)
				{
					top.window.BXIM.openMessenger(`chat${parseInt(response.data.chatId, 10)}`);

					return null;
				}

				alert(Loc.getMessage('EC_CONFERENCE_ERROR'));

				return null;
			},
			(response) => {
				console.error(response);

				alert(Loc.getMessage('EC_CONFERENCE_ERROR'));

				return null;
			},
		);
	}

	handleEditButtonClick(): void
	{
		const timezoneOffset = Type.isStringFilled(this.userTimezone)
			? -Util.getTimeZoneOffset(this.userTimezone, this.entry?.from) * 60
			: this.timezoneOffset
		;

		this.BX.SidePanel.Instance.close(false, () => {
			EntryManager.openEditSlider({
				entry: this.entry,
				type: this.type,
				ownerId: this.ownerId,
				userId: this.userId,
				timezoneOffset,
			});
		});
	}
}
